% vaib-fixed.tex -- scratch, not committed.
% Companion to vaib-decoupled.tex: the admission decision now requires
% absolute = zfalse, exactly PathContainedByFixed's extra conjunct in
% docs/spec-writeset-admission.tex. Same FileRaw state space; no
% deadlock should be reachable.
%
\documentclass[a4paper,10pt,fleqn]{article}
\usepackage[margin=1in]{geometry}
\usepackage{fuzz}
\begin{document}

\begin{zed}
SEG ::= segDocs | segXmd
\end{zed}

\begin{zed}
RAWSEG ::= rsSeg \ldata SEG \rdata | rsEmpty | rsDot
\end{zed}

\begin{zed}
PATSEG ::= litSeg \ldata SEG \rdata | wildRestSeg
\end{zed}

\begin{zed}
ZBOOL ::= ztrue | zfalse
\end{zed}

\begin{axdef}
maxSegs : \nat
\where
maxSegs = 2
\end{axdef}

\begin{axdef}
unwrap : RAWSEG \pfun SEG
\where
\forall s : SEG @ unwrap(rsSeg(s)) = s
\end{axdef}

\begin{axdef}
witnessPattern : \seq PATSEG
\where
witnessPattern = \langle litSeg(segDocs), wildRestSeg \rangle
\end{axdef}

\begin{schema}{FileRaw}
raw : \seq RAWSEG \\
segs : \seq SEG \\
absolute : ZBOOL \\
covered : ZBOOL \\
fixedAdmit : ZBOOL
\where
\# raw \leq maxSegs \\
segs = squash(raw \comp unwrap) \\
absolute = (\IF \# raw > 0 \land raw(1) = rsEmpty \THEN ztrue \ELSE zfalse) \\
(covered = ztrue \iff
  (\# witnessPattern = 0)
  \lor (\# witnessPattern > 0 \land witnessPattern(\# witnessPattern) = wildRestSeg
        \land (\# witnessPattern - 1) \leq \# segs
        \land (\forall i : 1 \upto (\# witnessPattern - 1) @ witnessPattern(i) = litSeg(segs(i))))
  \lor (\# witnessPattern > 0 \land witnessPattern(\# witnessPattern) \neq wildRestSeg
        \land \# witnessPattern \leq \# segs
        \land (\forall i : 1 \upto \# witnessPattern @ witnessPattern(i) = litSeg(segs(i))))) \\
(fixedAdmit = ztrue \iff (absolute = zfalse \land covered = ztrue))
\end{schema}

\begin{schema}{Init}
FileRaw'
\end{schema}

\begin{schema}{Idle}
\Xi FileRaw
\where
\lnot (absolute = ztrue \land fixedAdmit = ztrue)
\end{schema}

\end{document}

