%
% 8ady-decoupled.tex -- scratch, not committed.
%
% Decoupled reachability demonstration for ethos-8ady: mission lint's
% write_set coverage heuristic (lint.go:187-193) compares CanonicalPath's
% STRING output literally, so a glob write_set entry such as "docs/**"
% is compared character-for-character against a covered file, and the
% glob segment "**" is indistinguishable from a real segment named "**".
% Stringify below is that round trip made explicit: it is what a
% PATSEG becomes once CanonicalPath has joined it back into a plain
% string for lint's strings.HasPrefix call.
%
\documentclass[a4paper,10pt,fleqn]{article}
\usepackage[margin=1in]{geometry}
\usepackage{fuzz}
\begin{document}

\begin{zed}
SEG ::= segDocs | segFile | segStarStar
\end{zed}

\begin{zed}
PATSEG ::= litSeg \ldata SEG \rdata | wildRestSeg
\end{zed}

\begin{zed}
ZBOOL ::= ztrue | zfalse
\end{zed}

\begin{axdef}
maxSegs : \nat
\where
maxSegs = 2
\end{axdef}

\begin{axdef}
witnessEntry : \seq PATSEG
\where
witnessEntry = \langle litSeg(segDocs), wildRestSeg \rangle
\end{axdef}

\begin{schema}{FileSegs}
segs : \seq SEG \\
semanticCovered : ZBOOL \\
literalCovered : ZBOOL
\where
\# segs \leq maxSegs \\
(semanticCovered = ztrue \iff
  (\# witnessEntry = 0)
  \lor (\# witnessEntry > 0 \land witnessEntry(\# witnessEntry) = wildRestSeg
        \land (\# witnessEntry - 1) \leq \# segs
        \land (\forall i : 1 \upto (\# witnessEntry - 1) @ witnessEntry(i) = litSeg(segs(i))))
  \lor (\# witnessEntry > 0 \land witnessEntry(\# witnessEntry) \neq wildRestSeg
        \land \# witnessEntry \leq \# segs
        \land (\forall i : 1 \upto \# witnessEntry @ witnessEntry(i) = litSeg(segs(i))))) \\
(literalCovered = ztrue \iff
  \# witnessEntry < \# segs
  \land (\forall i : 1 \upto \# witnessEntry @
          (witnessEntry(i) = litSeg(segStarStar) \lor witnessEntry(i) = litSeg(segDocs)
           \lor witnessEntry(i) = litSeg(segFile))
          \land ((\exists s : SEG @ witnessEntry(i) = litSeg(s) \land s = segs(i))
                 \lor (witnessEntry(i) = wildRestSeg \land segs(i) = segStarStar))))
\end{schema}

\begin{schema}{Init}
FileSegs'
\end{schema}

\begin{schema}{Idle}
\Xi FileSegs
\where
\lnot (semanticCovered = ztrue \land literalCovered = zfalse)
\end{schema}

\end{document}

