\documentclass[a4paper,10pt,fleqn]{article}
\usepackage[margin=1in]{geometry}
\usepackage{fuzz}
\begin{document}

\begin{zed}
ZBOOL ::= ztrue | zfalse
\end{zed}

\begin{zed}
SEG ::= segA | segB
\end{zed}

\begin{axdef}
maxSegs : \nat
\where
maxSegs = 2
\end{axdef}

\begin{schema}{ENTRY}
isDir : ZBOOL \\
pattern : \seq SEG
\where
\# pattern \leq maxSegs
\end{schema}

\begin{axdef}
Overlaps : ENTRY \rel ENTRY
\where
\forall a, b : ENTRY @ (a \mapsto b \in Overlaps) \iff a.isDir = b.isDir
\end{axdef}

\begin{schema}{Store}
open : 1 \upto 2 \pfun ENTRY
\end{schema}

\begin{schema}{Init}
Store'
\where
open' = \emptyset
\end{schema}

\begin{schema}{AdmitMission}
\Delta Store \\
slot? : 1 \upto 2 \\
entry? : ENTRY
\where
slot? \notin \dom open \\
\forall i : \dom open @ \lnot (entry? \mapsto (open\ i) \in Overlaps) \\
open' = open \oplus \{ slot? \mapsto entry? \}
\end{schema}

\begin{schema}{ReleaseMission}
\Delta Store \\
slot? : 1 \upto 2
\where
slot? \in \dom open \\
open' = \{ slot? \} \ndres open
\end{schema}

\end{document}

